
package com.store.productservice.dto;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDateTime;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.format.annotation.DateTimeFormat.ISO;
public class ProductRequest { @NotBlank(message="Le nom est obligatoire") private String nom; @NotNull(message="Le prix est obligatoire") @DecimalMin(value="0.0", inclusive=true, message="Le prix doit être >= 0") private BigDecimal prix; @NotNull(message="La quantité est obligatoire") @Min(value=0, message="La quantité doit être >= 0") private Integer quantite; @NotNull(message="La date de création est obligatoire") @DateTimeFormat(iso=ISO.DATE_TIME) private LocalDateTime dateCreation; public String getNom(){return nom;} public void setNom(String nom){this.nom=nom;} public BigDecimal getPrix(){return prix;} public void setPrix(BigDecimal prix){this.prix=prix;} public Integer getQuantite(){return quantite;} public void setQuantite(Integer quantite){this.quantite=quantite;} public LocalDateTime getDateCreation(){return dateCreation;} public void setDateCreation(LocalDateTime dateCreation){this.dateCreation=dateCreation;} }
